    '</div>';
  var btn = document.getElementById('btnChangePassword');
  if (btn) btn.addEventListener('click', openChangePasswordModal);
}

function openChangePasswordModal() {
  var modal = document.getElementById('changePasswordModal');
  if (modal) modal.classList.remove('hidden');
}

function closeChangePasswordModal() {
  var modal = document.getElementById('changePasswordModal');
  if (modal) modal.classList.add('hidden');
  ['changePwdCurrent', 'changePwdNew', 'changePwdConfirm'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.value = '';
  });
  var err = document.getElementById('changePwdError');
  if (err) err.classList.add('hidden');
}

function submitChangePassword() {
  var err = document.getElementById('changePwdError');
  if (!global.UserAuth) return;
  var result = UserAuth.changePassword(
    (document.getElementById('changePwdCurrent') || {}).value,
    (document.getElementById('changePwdNew') || {}).value,
    (document.getElementById('changePwdConfirm') || {}).value
  );
  if (!result.ok) {
    if (err) { err.textContent = result.error; err.classList.remove('hidden'); }
    return;
  }
  closeChangePasswordModal();
  if (global.Proto && Proto.toast) Proto.toast('密码已更新');
}

