  });
  el.querySelectorAll('[data-kb-preview]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      if (global.Proto && Proto.toast) Proto.toast('原型：' + btn.getAttribute('data-kb-preview'));
    });
  });
}

