const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');

function read(rel) { return fs.readFileSync(path.join(root, rel), 'utf8'); }
function write(rel, content) { fs.writeFileSync(path.join(root, rel), content, 'utf8'); }
function replace(rel, oldStr, newStr, label) {
  const file = read(rel);
  if (!file.includes(oldStr)) throw new Error('NOT FOUND [' + label + '] in ' + rel);
  write(rel, file.replace(oldStr, newStr));
  console.log('OK', label, '->', rel);
}

